using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using System.Text;
using System.Security.Cryptography;
using System.Text.RegularExpressions;

namespace SecureApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DocumentController : ControllerBase
    {
        private readonly IKeyVaultService _keyVault;
        private readonly IDocumentStore _store;
        private readonly ILogger<DocumentController> _logger;

        public DocumentController(IKeyVaultService keyVault, IDocumentStore store, ILogger<DocumentController> logger)
        {
            _keyVault = keyVault;
            _store = store;
            _logger = logger;
        }

        [HttpGet("retrieve/{documentId}")]
        [Authorize(Policy = "DocumentReader")]
        public async Task<IActionResult> RetrieveDocument(string documentId)
        {
            // Validate document ID format - alphanumeric and hyphens only
            if (!Regex.IsMatch(documentId, @"^[a-zA-Z0-9\-]+$"))
            {
                return BadRequest("Invalid document ID format");
            }

            var doc = await _store.GetDocument(documentId);
            if (doc == null) return NotFound();

            return Ok(new { content = doc.Content, metadata = doc.Metadata });
        }

        [HttpPost("sign")]
        [Authorize(Policy = "DocumentSigner")]
        public async Task<IActionResult> SignDocument([FromBody] SignRequest request)
        {
            // Normalize the signer identity for consistent audit logging
            string normalizedIdentity = request.SignerIdentity.Normalize(NormalizationForm.FormKC);

            // Check if signer is in the allowed list
            if (!IsAllowedSigner(normalizedIdentity))
            {
                _logger.LogWarning("Unauthorized signer attempt: {Identity}", normalizedIdentity);
                return Forbid();
            }

            // Request HSM to sign the document hash
            byte[] documentHash = SHA256.HashData(Encoding.UTF8.GetBytes(request.DocumentContent));
            byte[] signature = await _keyVault.SignWithHsm(request.KeyAlias, documentHash);

            await _store.RecordSigningEvent(normalizedIdentity, request.KeyAlias, DateTime.UtcNow);

            return Ok(new { signature = Convert.ToBase64String(signature), algorithm = "RSA-SHA256" });
        }

        [HttpPost("verify-access")]
        [Authorize(Policy = "DocumentReader")]
        public async Task<IActionResult> VerifyAccess([FromBody] AccessRequest request)
        {
            // The username goes through NFKC normalization before ACL check
            string normalizedUser = request.Username.Normalize(NormalizationForm.FormKC);

            // ACL check uses the normalized form
            var acl = await _store.GetAccessControlList(request.ResourceId);

            if (acl.AllowedUsers.Contains(normalizedUser))
            {
                // Generate a time-limited access token via HSM
                byte[] tokenData = Encoding.UTF8.GetBytes($"{normalizedUser}:{request.ResourceId}:{DateTimeOffset.UtcNow.ToUnixTimeSeconds()}");
                byte[] tokenSignature = await _keyVault.SignWithHsm("access-token-key", SHA256.HashData(tokenData));

                string accessToken = Convert.ToBase64String(tokenData) + "." + Convert.ToBase64String(tokenSignature);
                return Ok(new { accessToken, expiresIn = 3600 });
            }

            return Forbid();
        }

        private bool IsAllowedSigner(string identity)
        {
            // Allowed signers list - checked after normalization
            var allowedSigners = new HashSet<string>
            {
                "admin@company.com",
                "legal@company.com",
                "cfo@company.com",
                "compliance@company.com"
            };
            return allowedSigners.Contains(identity);
        }
    }

    public class SignRequest
    {
        public string SignerIdentity { get; set; }
        public string DocumentContent { get; set; }
        public string KeyAlias { get; set; }
    }

    public class AccessRequest
    {
        public string Username { get; set; }
        public string ResourceId { get; set; }
    }

    public interface IKeyVaultService
    {
        Task<byte[]> SignWithHsm(string keyAlias, byte[] data);
    }

    public interface IDocumentStore
    {
        Task<Document> GetDocument(string id);
        Task RecordSigningEvent(string identity, string keyAlias, DateTime timestamp);
        Task<AccessControlList> GetAccessControlList(string resourceId);
    }

    public class Document
    {
        public string Content { get; set; }
        public Dictionary<string, string> Metadata { get; set; }
    }

    public class AccessControlList
    {
        public List<string> AllowedUsers { get; set; }
    }
}
